CREATE OR REPLACE FUNCTION public.fn_create_experience(p_id uuid, p_tenant_id uuid, p_organization_id uuid, p_title character varying, p_description text, p_status character varying, p_dna_payload jsonb, p_created_by_user_id uuid, p_created_at timestamp with time zone, p_updated_at timestamp with time zone, p_version_id uuid DEFAULT gen_random_uuid())  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, title character varying, description text, status character varying, dna_payload jsonb, created_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     INSERT INTO experiences (id, tenant_id, organization_id, title, description, status, dna_payload, created_by_user_id, created_at, updated_at)     VALUES (p_id, p_tenant_id, p_organization_id, p_title, p_description, p_status, p_dna_payload, p_created_by_user_id, p_created_at, p_updated_at);      INSERT INTO experience_versions (id, experience_id, version_number, title, description, dna_payload, change_reason, modified_by_user_id, created_at)     VALUES (p_version_id, p_id, 1, p_title, p_description, p_dna_payload, 'Initial Creation', p_created_by_user_id, p_created_at);      RETURN QUERY     SELECT e.id, e.tenant_id, e.organization_id, e.title, e.description, e.status, e.dna_payload, e.created_by_user_id, e.created_at, e.updated_at     FROM experiences e     WHERE e.id = p_id; END; $function$ ;
